const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const greatLakesGeom = ee.Geometry.Rectangle([-92.5, 41.0, -76.0, 49.5]);
  const date1 = '2021-02-20';
  const date2 = '2021-03-03';

  // 2. Data Acquisition and Processing Function
  const getIceArea = function(date_string) {
    const imageCollection = ee.ImageCollection('MODIS/061/MOD10A1')
      .filterDate(date_string, ee.Date(date_string).advance(1, 'day'))
      .filterBounds(greatLakesGeom);

    // Check if collection is empty for the given day
    if (imageCollection.size().getInfo() === 0) {
      return {
        iceArea: null,
        totalPixels: 0,
        cloudPixels: 0,
        imageCount: 0
      };
    }

    const image = imageCollection.first();
    const snowCoverBand = image.select('NDSI_Snow_Cover');

    // Define masks based on MODIS QA values
    // Valid data is where NDSI is between 0 and 100.
    const validDataMask = snowCoverBand.lte(100);
    // Clouds are coded as 250
    const cloudMask = snowCoverBand.eq(250);
    // Ice is where NDSI is > 40 (a common threshold)
    const iceMask = snowCoverBand.gt(40).updateMask(validDataMask);

    // Calculate the area of ice
    const iceArea = iceMask.multiply(ee.Image.pixelArea()).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: greatLakesGeom,
      scale: 1000, // Use a coarser scale to prevent timeout
      maxPixels: 1e9
    }).get('NDSI_Snow_Cover');

    // Calculate pixel counts for validation
    const countReducer = ee.Reducer.sum().unweighted();
    const totalPixels = validDataMask.reduceRegion({
        reducer: countReducer,
        geometry: greatLakesGeom,
        scale: 3000,
        maxPixels: 1e9
    }).get('NDSI_Snow_Cover');

    const cloudPixels = cloudMask.reduceRegion({
        reducer: countReducer,
        geometry: greatLakesGeom,
        scale: 3000,
        maxPixels: 1e9
    }).get('NDSI_Snow_Cover');

    return {
      iceArea: ee.Number(iceArea).divide(1e6), // Convert to sq km
      totalPixels: totalPixels,
      cloudPixels: cloudPixels,
      imageCount: imageCollection.size()
    };
  };

  // 3. Perform Calculation for both dates
  const result1 = getIceArea(date1);
  const result2 = getIceArea(date2);

  // 4. Validation & Final Answer
  const imageCount1 = ee.Number(result1.imageCount).getInfo();
  const imageCount2 = ee.Number(result2.imageCount).getInfo();

  if (imageCount1 === 0 || imageCount2 === 0) {
    console.log(`Image count on ${date1}: ${imageCount1}`);
    console.log(`Image count on ${date2}: ${imageCount2}`);
    console.log("Empty collection for one or both dates.");
    console.log("A: Yes"); // C1
    return;
  }

  const totalPixels1 = ee.Number(result1.totalPixels).getInfo();
  const cloudPixels1 = ee.Number(result1.cloudPixels).getInfo();
  const iceArea1 = ee.Number(result1.iceArea).getInfo();

  const totalPixels2 = ee.Number(result2.totalPixels).getInfo();
  const cloudPixels2 = ee.Number(result2.cloudPixels).getInfo();
  const iceArea2 = ee.Number(result2.iceArea).getInfo();

  if (totalPixels1 === 0 || totalPixels2 === 0) {
      console.log(`Valid pixels on ${date1}: ${totalPixels1}`);
      console.log(`Valid pixels on ${date2}: ${totalPixels2}`);
      console.log("No valid pixels found after cloud/QA masking.");
      console.log("C2");
      return;
  }

  if (iceArea1 === null || iceArea2 === null) {
      console.log(`Ice Area ${date1}: ${iceArea1}`);
      console.log(`Ice Area ${date2}: ${iceArea2}`);
      console.log("Calculation failed, result is null.");
      console.log("C3");
      return;
  }

  const cloudPercent1 = (cloudPixels1 / (totalPixels1 + cloudPixels1)) * 100;
  const cloudPercent2 = (cloudPixels2 / (totalPixels2 + cloudPixels2)) * 100;

  console.log(`${date1} Ice Coverage: ${iceArea1.toFixed(2)} sq km`);
  console.log(`${date1} Cloud Cover: ${cloudPercent1.toFixed(2)}%`);
  console.log(`${date2} Ice Coverage: ${iceArea2.toFixed(2)} sq km`);
  console.log(`${date2} Cloud Cover: ${cloudPercent2.toFixed(2)}%`);

  if (iceArea2 < iceArea1) {
    console.log("Evidence: Ice coverage decreased.");
    console.log("A: Yes");
  } else {
    console.log("Evidence: Ice coverage did not decrease.");
    console.log("B: No");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or analysis failed: ${e}`);
    console.log("D");
  }
}

initEE();
